from __future__ import annotations
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
def load(p):return json.loads((ROOT/p).read_text())
def bi(en,fr):return {'en':en,'fr':fr}
def main():
 audit=load('results/independent-followup-audit/summary.json')
 bridge=load('market/production-followup.json')
 titles={'F01':bi('Flask startup banner','Bannière de démarrage Flask'),'F02':bi('Black output formatting','Formatage des sorties Black'),'F03':bi('NetworkX eigenvector centrality','Centralité de vecteur propre NetworkX'),'F04':bi('Hugging Face HTTP client factories','Fabriques de clients HTTP Hugging Face')}
 notes={
 'F01':bi('Both captured Click echo signatures preserve argument binding. Confirm the imported targets and test the startup-banner paths under both versions before approving an upgrade.','Les deux signatures Click echo conservent la liaison des arguments. Confirmez les cibles importées et testez les chemins de bannière avec les deux versions avant toute approbation.'),
 'F02':bi('The echo calls bind to both captured declarations. Expanded **styles remain unresolved: test the output and error formatting with representative style dictionaries under both versions.','Les appels echo correspondent aux deux déclarations capturées. **styles reste non résolu : testez les sorties et erreurs avec des dictionnaires de style représentatifs dans les deux versions.'),
 'F03':bi('Captured eigs and norm call signatures preserve binding. Runtime import identity and numerical behavior remain unverified. C2 incorrectly adds two NumPy data methods, so its complete handoff is rejected.','Les signatures capturées de eigs et norm conservent la liaison. L’identité des imports et le comportement numérique restent non vérifiés. C2 ajoute à tort deux méthodes de données NumPy : son livrable complet est rejeté.'),
 'F04':bi('Client and Timeout declarations are captured, but ordinary constructor dispatch is outside the unchanged verifier’s supported proof. Hold approval and exercise both client factories under both versions.','Les déclarations Client et Timeout sont capturées, mais la résolution des constructeurs dépasse la preuve du vérificateur inchangé. Suspendez l’approbation et testez les deux fabriques avec les deux versions.')}
 missions=[]
 for task in bridge['missions']:
  raw=load(f'inputs/followup/{task}.json');consumer=raw['sources']['consumer'];arms={}
  for arm in ['A','B','C']:
   result=load(f'results/followup/{task}/{arm}/delivery/result.json');inv=load(f'results/followup/{task}/{arm}/delivery/call-inventory.json')
   row=next(r for r in audit['rows'] if r['task']==task and r['arm']==arm)
   core=result.get('coreRecord')
   if core:
    core=json.loads(json.dumps(core));byid={x['id']:x for x in inv}
    for call in core['calls']:
     extra=byid.get(call['id'],{});call.update({k:extra[k] for k in ['callee','line','column','snippet'] if k in extra})
     if not call.get('evidence') and extra:call['evidence']=[{'sourceId':'consumer','line':extra['line'],'endLine':extra['line'],'url':extra['consumerUrl']}]
   arms[arm]={'accepted':row['completeHandoffAccepted'],'nextAction':result['nextAction'],'selectedCalls':len(inv),'coreRecord':core,'unresolvedIntake':result['unresolvedIntake'],'resources':result['resources'],'notes':notes[task],'callInventory':inv,'independentReview':row,'resultSha256':row['resultSha256'],'sealedResult':result,'presentationEnrichment':'Display call names/snippets are joined from the independently checked call inventory; sealedResult retains the original outcome bytes semantically.','costs':load(f'results/followup/{task}/{arm}/delivery/costs.json')}
  missions.append({'id':task,'title':titles[task],'dependency':raw['dependency'],'consumerRepo':consumer['repository'],'rawInput':raw,'sourceLinks':[{'label':bi('Immutable consumer source','Source consommateur immuable'),'url':f"https://github.com/{consumer['repository']}/blob/{consumer['commit']}/{consumer['path']}"}],'arms':arms})
 data={'schema':'agi-alpha-transfer-demo/v1','title':bi('AGI ALPHA · Productive Advantage','AGI ALPHA · Avantage productif'),'summary':{'headline':bi('A useful review. An unproven investment.','Une revue utile. Un investissement non établi.'),'finding':bi('Fresh complete handoffs: incumbent A 4/4, model-assisted B 4/4, ordinary C2 3/4. Complete monetary costs remain unknown.','Livrables frais complets : référence A 4/4, modèle B 4/4, outil classique C2 3/4. Les coûts monétaires complets restent inconnus.'),'evidenceStatus':bi('Measured source work · conditional economics · zero actual collections','Travail sur sources mesuré · économie conditionnelle · aucun encaissement réel')},'missions':missions,'capability':{'title':bi('Structured source intake → exact verification','Extraction structurée → vérification exacte'),'path':bridge['arms']['B']['asset']['path'],'sha256':bridge['arms']['B']['asset']['sha256'],'mechanism':bi('A frozen model prompt proposes captured declarations; a typed compiler and the unchanged AGI ALPHA core verify exact source and supported binding. Four fresh complete handoffs pass.','Un prompt figé propose des déclarations capturées ; un compilateur typé et le cœur AGI ALPHA inchangé vérifient les sources et la liaison prise en charge. Quatre livrables frais complets sont acceptés.'),'boundary':bi('B matches the incumbent on accepted work; no complete cost, quality or customer-effort advantage is identified. C2 fails one full-scope task and cannot receive a model-free cost discount.','B égale la référence sur les livrables acceptés ; aucun avantage de coût complet, de qualité ou d’effort client n’est identifié. C2 échoue sur une tâche complète et ne bénéficie pas d’une réduction de coût sans modèle.')},'primaryConfirmation':{'finding':bi('Preserved primary: 6/6 inventories in every arm, but 0/6 complete handoffs. A/B found the same conditional SciPy eigvals conflict; the first C used an unfairly strict export-proof rule. The fresh follow-up is separate and does not repair those results.','Résultat primaire conservé : 6/6 inventaires pour chaque bras, mais 0/6 livrables complets. A/B ont trouvé le même conflit conditionnel SciPy eigvals ; le premier C exigeait une preuve d’export trop stricte. Le suivi frais est distinct et ne corrige pas rétroactivement ces résultats.'),'sourceLinks':[{'label':bi('Coordination and preserved study lanes','Coordination et études conservées'),'url':'https://github.com/MontrealAI/AGI-Alpha-Agent-v0/issues/4850'}]},'priorMarkets':{'summary':bi('All 19,440 previous enterprise histories were independently reconciled. Primary, exploratory and fixed-price diagnostic results remain separate.','Les 19 440 historiques antérieurs ont été rapprochés indépendamment. Les résultats primaires, exploratoires et du diagnostic de prix fixe restent séparés.'),'primaryNegative':bi('Previous primary: 0 investments in 6,264 enterprises. Across all three campaigns: 0 investments financed by earned operating surplus. A diagnosed pricing defect does not erase the primary negative result.','Primaire antérieur : 0 investissement dans 6 264 entreprises. Sur les trois campagnes : 0 investissement financé par un surplus d’exploitation gagné. Le défaut de prix diagnostiqué n’efface pas ce résultat négatif.'),'sourceLinks':[]},'productionMarketRecord':bridge,'sources':[
 {'title':'Virtual Agent Economies','url':'https://arxiv.org/abs/2509.10147v1','version':'v1','license':'CC BY 4.0','role':bi('Conceptual market design; no demand calibration imported.','Conception conceptuelle du marché ; aucune demande calibrée importée.')},
 {'title':'DUPLEX','url':'https://arxiv.org/abs/2603.23909v1','version':'v1','license':'CC BY 4.0','role':bi('Structured-extraction principle adapted and executed; original planning results not reproduced.','Principe d’extraction structurée adapté et exécuté ; résultats de planification originaux non reproduits.')},
 {'title':'OpenEvolve','url':'https://github.com/algorithmicsuperintelligence/openevolve','version':'0.4.0 / 66856ac4ba2f','license':'Apache-2.0','role':bi('Reviewed, not installed or evaluated; no justified costly search target.','Examiné, sans installation ni évaluation ; aucune cible coûteuse justifiée.')},
 {'title':'EnvHarness','url':'https://arxiv.org/abs/2608.19880v1','version':'v1 / fab7d57441f0','license':'Paper CC BY 4.0; code Apache-2.0','role':bi('Reviewed, not evaluated; independent fresh acceptance retained.','Examiné, non évalué ; acceptation indépendante sur des entrées fraîches conservée.')},
 {'title':'BLS · developer and QA wage anchors','url':'https://www.bls.gov/ooh/computer-and-information-technology/software-developers.htm','version':'May 2025 pay','license':'Official source','role':bi('Sourced wage anchors only; no measured human duration or elapsed-agent wage conversion.','Repères salariaux sourcés uniquement ; aucune durée humaine mesurée ni conversion du temps agent en salaire.')}],
 'limitations':[bi('Four fresh historical source tasks are not four customers or a field-reliability estimate.','Quatre tâches historiques fraîches ne sont ni quatre clients ni une estimation de fiabilité en production.'),bi('All 166 planned three-arm market cells remain unexecuted because C2 fails complete equivalence; no favorable subset is substituted.','Les 166 cellules prévues à trois bras restent inexécutées car C2 échoue à l’équivalence complète ; aucun sous-ensemble favorable ne lui est substitué.'),bi('Frozen customer reports pass their stated checks, but an auxiliary Workbench source locator was wrong; publication navigation aliases are separately documented.','Les rapports clients figés satisfont leurs contrôles, mais un lien auxiliaire Workbench était incorrect ; les alias de navigation de publication sont documentés séparément.')],
 'actualCustomerCollectionsUsd':0,'threeArmCampaign':{'status':'GATED_UNEXECUTED','registeredCells':166}}
 ab=ROOT/'market/accepted-ab-diagnostic/production-accepted-ab.json'
 if ab.exists():data['acceptedABDiagnosticProduction']=json.loads(ab.read_text())
 data['acceptedABScenarioDefaults']={'financing':'operating-surplus','shared':{'pricingPolicy':'fixed','initialPriceCents':2000,'arrivalProbability':0.25,'integrationCents':1000,'nextAsset':None},'costs':{'A':{'completeRecurringCostCents':500,'completeConstructionCostCents':0,'maintenancePerWeekCents':0,'assumedIntakeMinutes':0},'B':{'completeRecurringCostCents':500,'completeConstructionCostCents':10000,'maintenancePerWeekCents':50,'assumedIntakeMinutes':0}}}
 (ROOT/'publication/demo-data.json').write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
 print(json.dumps({'missions':len(missions),'threeArmGate':'FAIL','acceptedABDiagnosticProductionIncluded':ab.exists()}))
if __name__=='__main__':main()
